import React from 'react';
import { graphql } from 'gatsby';
import { useTranslation } from 'gatsby-plugin-react-i18next';
import styled from 'styled-components';
import Layout from '../components/layout/Layout';

const TeachingHero = styled.section`
  min-height: 40vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: ${props => props.theme.space[20]} ${props => props.theme.space[6]};
  background: linear-gradient(
    135deg,
    var(--color-bg) 0%,
    var(--color-surface) 100%
  );
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: radial-gradient(
      circle at 60% 40%,
      rgba(247, 147, 30, 0.15) 0%,
      transparent 60%
    );
    pointer-events: none;
  }
`;

const HeroContent = styled.div`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  position: relative;
  z-index: 1;
  text-align: center;
`;

const Title = styled.h1`
  font-size: ${props => props.theme.typography.fontSizes['6xl']};
  margin-bottom: ${props => props.theme.space[4]};
  background: linear-gradient(
    135deg,
    ${props => props.theme.colors.accent} 0%,
    ${props => props.theme.colors.secondary} 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    font-size: ${props => props.theme.typography.fontSizes['4xl']};
  }
`;

const Subtitle = styled.p`
  font-size: ${props => props.theme.typography.fontSizes.xl};
  color: var(--color-text-secondary);
  max-width: 700px;
  margin: 0 auto;
  line-height: ${props => props.theme.typography.lineHeights.relaxed};
`;

const TeachingSection = styled.section`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  padding: ${props => props.theme.space[16]} ${props => props.theme.space[6]};
`;

const Content = styled.div`
  background: var(--color-surface);
  border-radius: ${props => props.theme.radii.xl};
  padding: ${props => props.theme.space[10]};
  border: 1px solid var(--color-border);

  h2 {
    font-size: ${props => props.theme.typography.fontSizes['3xl']};
    color: var(--color-text);
    margin-bottom: ${props => props.theme.space[6]};
  }

  p {
    color: var(--color-text-secondary);
    font-size: ${props => props.theme.typography.fontSizes.lg};
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
    margin-bottom: ${props => props.theme.space[4]};
  }
`;

function TeachingPage({ data }) {
  const { t } = useTranslation();

  return (
    <Layout
      title={t('teaching.title', 'Teaching')}
      description="Courses and teaching materials"
      path="/teaching"
    >
      <TeachingHero>
        <HeroContent>
          <Title>{t('teaching.title', 'Teaching')}</Title>
          <Subtitle>
            {t('teaching.subtitle', 'Courses and Teaching Materials')}
          </Subtitle>
        </HeroContent>
      </TeachingHero>

      <TeachingSection>
        <Content>
          <h2>Coming Soon</h2>
          <p>
            This page will display information about courses, workshops, and teaching materials.
            Organize your courses by years, topics, or universities!
          </p>
        </Content>
      </TeachingSection>
    </Layout>
  );
}

export default TeachingPage;

export const query = graphql`
  query TeachingPageQuery($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
